INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jede IT-Maßnahme automatisch alle Risiken ausschließt?', 2, '[{"text": "Nein", "correct": true, "because": "Restrisiken bleiben oft bestehen"}, {"text": "Ja", "correct": false, "because": "Keine Maßnahme ist absolut"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist bei der Analyse von IT-Risiken entscheidend?', 3, '[{"text": "Identifikation potenzieller Schwachstellen", "correct": true, "because": "Erkennt Gefahrenquellen"}, {"text": "Maximale Hardwareleistung", "correct": false, "because": "Irrelevant für Sicherheit"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Genauigkeit zählt mehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen helfen, IT-Systeme gegen Bedrohungen zu schützen?', 5, '[{"text": "Regelmäßige Updates", "correct": true, "because": "Schließt bekannte Lücken"}, {"text": "Zugriffskontrollen", "correct": true, "because": "Begrenzt unbefugten Zugriff"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Verbessert nur Leistung"}, {"text": "Bunte Benutzeroberfläche", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Risiko muss immer quantifiziert werden. b) Technische Maßnahmen haben Vorrang vor organisatorischen.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Quantifizierung nicht zwingend, Maßnahmen gleichwertig"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist kontextabhängig"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beide sind falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Absicherung eines Servers?', 4, '[{"text": "Patch-Management", "correct": false, "because": "Schließt Sicherheitslücken"}, {"text": "Firewall-Konfiguration", "correct": false, "because": "Schützt vor Angriffen"}, {"text": "Farbe des Gehäuses", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Virenscanner alle Bedrohungen abwehrt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann nicht alle Angriffe erkennen"}, {"text": "Ja", "correct": false, "because": "Begrenzt auf bekannte Muster"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich Schwachstellen in einem Netzwerk prüfe?', 3, '[{"text": "Minimierung von Angriffsflächen", "correct": true, "because": "Reduziert Risiken"}, {"text": "Erhöhung der Bandbreite", "correct": false, "because": "Kein Sicherheitsziel"}, {"text": "Verkürzung der Latenz", "correct": false, "because": "Leistungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei der Absicherung eines Systems relevant?', 5, '[{"text": "Zugriffsbeschränkungen", "correct": true, "because": "Verhindert unbefugten Zugriff"}, {"text": "Datenverschlüsselung", "correct": true, "because": "Schützt Vertraulichkeit"}, {"text": "Schnelle Prozessoren", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Großer Arbeitsspeicher", "correct": false, "because": "Nur Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine einmalige Prüfung eines Systems ausreichend?', 2, '[{"text": "Nein", "correct": true, "because": "Neue Bedrohungen entstehen ständig"}, {"text": "Ja", "correct": false, "because": "Regelmäßigkeit erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Dokumentation bei der Sicherheitsanalyse?', 4, '[{"text": "Nachvollziehbarkeit von Maßnahmen", "correct": true, "because": "Ermöglicht Audits"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Dokumentationsziel"}, {"text": "Vereinfachte Installation", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob physische Sicherheit bei IT-Risiken egal ist?', 3, '[{"text": "Nein", "correct": true, "because": "Zugriff auf Hardware ist kritisch"}, {"text": "Ja", "correct": false, "because": "Physische Angriffe sind relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme priorisiere ich bei sensiblen Daten?', 4, '[{"text": "Ende-zu-Ende-Verschlüsselung", "correct": true, "because": "Schützt Daten während Übertragung"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Schnelle Netzwerkkarte", "correct": false, "because": "Nur Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Backups allein vor Datenverlust schützen. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Ohne Tests unsicher"}, {"text": "Ja", "correct": false, "because": "Wiederherstellbarkeit muss geprüft werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Passwort allein sichert ein System. b) Mehrfaktor-Authentifizierung erhöht Sicherheit.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Passwörter sind oft schwach"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine sichere Netzwerkumgebung?', 4, '[{"text": "Intrusion Detection", "correct": false, "because": "Erkennt Angriffe"}, {"text": "Segmentierung", "correct": false, "because": "Begrenzt Schadensausbreitung"}, {"text": "Helle Beleuchtung", "correct": true, "because": "Kein IT-Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützt eine Firewall auch vor Social Engineering?', 3, '[{"text": "Nein", "correct": true, "because": "Zielt auf menschliches Verhalten"}, {"text": "Ja", "correct": false, "because": "Firewall ist technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Backup-System zuverlässig?', 5, '[{"text": "Regelmäßige Tests", "correct": true, "because": "Sichert Wiederherstellbarkeit"}, {"text": "Offsite-Speicherung", "correct": true, "because": "Schützt vor physischen Schäden"}, {"text": "Schnelle Festplatten", "correct": false, "because": "Nur Leistungsfaktor"}, {"text": "Bunte Etiketten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Schulungen für Mitarbeiter Risiken senken?', 2, '[{"text": "Ja", "correct": true, "because": "Fördert Sicherheitsbewusstsein"}, {"text": "Nein", "correct": false, "because": "Reduziert menschliche Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Vorgehen wähle ich bei einer neuen Software?', 4, '[{"text": "Prüfung auf Sicherheitslücken", "correct": true, "because": "Verhindert Exploits"}, {"text": "Schnelle Installation", "correct": false, "because": "Risiko ohne Prüfung"}, {"text": "Maximale Nutzerrechte", "correct": false, "because": "Erhöht Angriffsfläche"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Risiko nur technisch sein kann. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Menschliche und organisatorische Faktoren zählen"}, {"text": "Ja", "correct": false, "because": "Risiken sind vielfältig"}]');
